import { BlockTypes, ItemStack, TicksPerSecond } from "@minecraft/server";
import { ProgressAgesProcedure } from "BigBrain/Procedures/ProgressAgesProcedure";
import { PassiveRoutine } from "BigBrain/Routines/PassiveRoutine";
import AgesData from "Data/AgesData";
import V3 from "Helpers/Vectors/V3";
import VirtualInventoryComponent from "Inventory/VirtualInventoryComponent";
import AsyncUtils from "Utils/AsyncUtils";
import TestUtil from "Test/TestUtil";
import AbstractPassiveTest from "./AbstractPassiveTest";
class ReachDiamondAgeUsingChestsTest extends AbstractPassiveTest {
    async run(test) {
        // AIP in one corner
        const aip = this.spawnAIP(test, new V3(1, 2, 1), {
            root: PassiveRoutine
        });
        // Home Marker
        const bedTestLocation = new V3(13, 2, 13);
        TestUtil.createHome(test, bedTestLocation);
        // Two chests beside the home marker with materials split between them
        const chest1Location = new V3(12, 2, 13);
        test.setBlockType(BlockTypes.get("minecraft:chest"), chest1Location);
        this.setupChest1(test.getBlock(chest1Location));
        const chest2Location = new V3(10, 2, 13);
        test.setBlockType(BlockTypes.get("minecraft:chest"), chest2Location);
        this.setupChest2(test.getBlock(chest2Location));
        await test.idle(1);
        this.setupAIPInventory(aip);
        const bigBrain = aip.getMobComponent("BigBrainComponent");
        const progressAgesRoutine = bigBrain.root.getSubstate(ProgressAgesProcedure);
        await AsyncUtils.waitForCondition(()=>progressAgesRoutine.currentAge === "diamond");
        // Ensure the AI has iron age items
        for (const item of AgesData.IronAgeRequirements){
            const has = VirtualInventoryComponent.get(aip).hasItemType(item.id);
            test.assert(has, `AIP missing ${item.id}`);
        }
        // Ensure AI has nothing from the stone age
        for (const item of AgesData.StoneAgeRequirements){
            const has = VirtualInventoryComponent.get(aip).hasItemType(item.id);
            test.assert(!has, `AIP should not have ${item.id}`);
        }
        // Ensure AI has torches and beef
        test.assert(VirtualInventoryComponent.get(aip).hasItemType("minecraft:torch"), "AIP missing torch");
        test.assert(VirtualInventoryComponent.get(aip).hasItemType("minecraft:cooked_beef"), "AIP missing cooked beef");
        test.succeed();
    }
    setupAIPInventory(aip) {
        // Give AIP wood and stone tools (inferior gear — should be deposited after crafting)
        const inv = VirtualInventoryComponent.get(aip);
        inv.giveItem(new ItemStack("minecraft:wooden_pickaxe"));
        inv.giveItem(new ItemStack("minecraft:wooden_axe"));
        inv.giveItem(new ItemStack("minecraft:wooden_shovel"));
        inv.giveItem(new ItemStack("minecraft:wooden_sword"));
        inv.giveItem(new ItemStack("minecraft:stone_pickaxe"));
        inv.giveItem(new ItemStack("minecraft:stone_axe"));
        inv.giveItem(new ItemStack("minecraft:stone_shovel"));
        inv.giveItem(new ItemStack("minecraft:stone_sword"));
    }
    setupChest1(chest) {
        const container = InventoryUtil.getContainer(chest);
        if (!container) return;
        // Raw materials for crafting
        container.addItem(new ItemStack("minecraft:cobblestone", 64));
        container.addItem(new ItemStack("minecraft:raw_copper", 64));
        container.addItem(new ItemStack("minecraft:copper_ingot", 32));
        container.addItem(new ItemStack("minecraft:coal", 64));
        // Supplies
        container.addItem(new ItemStack("minecraft:torch", 64));
    }
    setupChest2(chest) {
        const container = InventoryUtil.getContainer(chest);
        if (!container) return;
        // More raw materials for crafting
        container.addItem(new ItemStack("minecraft:oak_log", 64));
        container.addItem(new ItemStack("minecraft:raw_iron", 64));
        container.addItem(new ItemStack("minecraft:iron_ingot", 32));
        // Supplies
        container.addItem(new ItemStack("minecraft:cooked_beef", 8));
    }
    constructor(...args){
        super(...args);
        this.identifier = "reach_diamond_age_using_chests";
        this.structure = "bedrock_box";
        this.maxTicks = 10 * 60 * TicksPerSecond;
    }
}
export { ReachDiamondAgeUsingChestsTest as default };

